

class Solution:
    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:
        n = len(s)
        stack = set()
        prefix = [0]*(n+1)
        if s[n-1] == '1':
            return False
        stack.add(0)
        prefix[1] = 1
        for i in range(1, n):
            prefix[i+1] = prefix[i]

            if s[i] == '0':
                prefix_sum = prefix[i-minJump+1] - prefix[max(0, i-maxJump)]
                if prefix_sum > 0:
                    prefix[i+1] += 1

        return prefix[n-1-minJump+1] - prefix[max(0, n-1-maxJump)] > 0
